solution.code:
public class Main {
    public static void main(String[] args) {
        int[][] a = {{2, 0}, {1, 3}};
        int[][] b = {{1, 4}, {5, 2}};
        int[][] c = new int[2][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                for (int k = 0; k < 2; k++) {
                    c[i][j] += a[i][k] * b[k][j];
                }
            }
        }
        for (int[] row : c) {
            System.out.println(row[0] + " " + row[1]);
        }
    }
}
